<?php
session_start();
if (($_SESSION["role"] ?? "") !== "admin" || empty($_SESSION["user_id"])) { header("Location: login.php"); exit; }
require "connection.php"; mysqli_report(MYSQLI_REPORT_OFF);
function memberEscape($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, "UTF-8"); }
if (empty($_SESSION["admin_csrf"])) $_SESSION["admin_csrf"]=bin2hex(random_bytes(32)); $csrf=$_SESSION["admin_csrf"]; $message="";
if($_SERVER["REQUEST_METHOD"]==="POST") { if(!isset($_POST["csrf_token"])||!hash_equals($csrf,(string)$_POST["csrf_token"])) {http_response_code(400);exit("Invalid form token.");} $id=(int)($_POST["id"]??0); $action=(string)($_POST["action"]??"");
 if($action==="role") { $role=(string)($_POST["role"]??""); $check=mysqli_prepare($conn,"SELECT username FROM register WHERE id=?");mysqli_stmt_bind_param($check,"i",$id);mysqli_stmt_execute($check);$target=mysqli_fetch_assoc(mysqli_stmt_get_result($check)); if(!$target||!in_array($role,["user","admin"],true)) $message="Select a valid member and permission."; elseif($target["username"]==="admin") $message="The main admin permission cannot be changed."; else {$stmt=mysqli_prepare($conn,"UPDATE register SET role=? WHERE id=?");mysqli_stmt_bind_param($stmt,"si",$role,$id);$message=mysqli_stmt_execute($stmt)?"Member permission updated.":"Could not update member permission.";} }
 elseif($action==="delete") { $check=mysqli_prepare($conn,"SELECT username FROM register WHERE id=?");mysqli_stmt_bind_param($check,"i",$id);mysqli_stmt_execute($check);$target=mysqli_fetch_assoc(mysqli_stmt_get_result($check)); if(!$target||$target["username"]==="admin"||$id===(int)$_SESSION["user_id"]) $message="The main admin and your current account cannot be removed here."; else {$stmt=mysqli_prepare($conn,"DELETE FROM register WHERE id=?");mysqli_stmt_bind_param($stmt,"i",$id);$message=mysqli_stmt_execute($stmt)?"Member removed.":"Could not remove member.";} }
}
$members=mysqli_query($conn,"SELECT id,firstname,lastname,phone,username,city,state,role,created_at FROM register ORDER BY role DESC, created_at DESC,id DESC");
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Members | Plantify Admin</title><link rel="stylesheet" href="styles/style.css?v=admin-style-2"></head><body class="admin-page"><?php include "admin_header.php"; ?><main class="admin-shell"><h1>Members</h1><p>Change member permissions or remove an account. Admin accounts can manage the panel.</p><?php if($message!==''): ?><p class="admin-message" role="status"><?=memberEscape($message)?></p><?php endif; ?><section class="admin-card"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Member</th><th>Contact</th><th>Location</th><th>Permission</th><th>Joined</th><th>Actions</th></tr></thead><tbody><?php if($members&&mysqli_num_rows($members)):while($m=mysqli_fetch_assoc($members)): ?><tr><td><?=memberEscape($m["firstname"]." ".$m["lastname"])?><br><strong><?=memberEscape($m["username"])?></strong></td><td><?=memberEscape($m["phone"])?></td><td><?=memberEscape($m["city"].", ".$m["state"])?></td><td><?=memberEscape($m["username"]==="admin"?"Admin":ucfirst($m["role"]??"user"))?></td><td><?=memberEscape($m["created_at"]??"")?></td><td class="admin-row-actions"><?php if($m["username"]!=="admin"): ?><form method="post"><input type="hidden" name="csrf_token" value="<?=memberEscape($csrf)?>"><input type="hidden" name="id" value="<?=(int)$m["id"]?>"><input type="hidden" name="action" value="role"><select name="role" aria-label="Permission for <?=memberEscape($m["username"])?>"><option value="user" <?=($m["role"]??"user")==="user"?"selected":""?>>Member</option><option value="admin" <?=($m["role"]??"user")==="admin"?"selected":""?>>Admin</option></select><button type="submit">Save role</button></form><?php endif; ?><?php if($m["username"]!=="admin"&&(int)$m["id"]!==(int)$_SESSION["user_id"]): ?><form method="post"><input type="hidden" name="csrf_token" value="<?=memberEscape($csrf)?>"><input type="hidden" name="id" value="<?=(int)$m["id"]?>"><input type="hidden" name="action" value="delete"><button class="admin-danger" type="submit">Remove member</button></form><?php else: ?><small>Main admin account is protected.</small><?php endif; ?></td></tr><?php endwhile; else: ?><tr><td colspan="6">No members found.</td></tr><?php endif; ?></tbody></table></div></section></main></body></html>
